reset role;
select is((select url_slug from public.referral_partners where id='f8200000-0000-4000-8000-000000000001'),'fixture-partner-1','business names produce readable aliases');
select ok(not has_table_privilege('authenticated','public.referral_partner_aliases','SELECT') and not has_table_privilege('service_role','public.referral_partner_aliases','UPDATE'),'aliases have no direct API access');
insert into public.referral_partners(id,business_name,city,contact_email,commission_amount_minor_units,created_by_user_id)
values('f8200000-0000-4000-8000-000000000004','Fixture Partner 1','St Louis','slug4@example.test',3000,'f8100000-0000-4000-8000-000000000001'),
('f8200000-0000-4000-8000-000000000005','Fixture Partner 1','St Louis','slug5@example.test',3000,'f8100000-0000-4000-8000-000000000001');
select is((select url_slug from public.referral_partners where id='f8200000-0000-4000-8000-000000000004'),'fixture-partner-1-st-louis','duplicate names use a city suffix');
select is((select url_slug from public.referral_partners where id='f8200000-0000-4000-8000-000000000005'),'fixture-partner-1-st-louis-2','city collisions use a number');
select throws_ok($$update public.referral_partner_aliases set partner_id='f8200000-0000-4000-8000-000000000002' where slug='fixture-partner-1'$$,'55000',null,'aliases cannot move to another business');
select throws_ok($$delete from public.referral_partner_aliases where slug='fixture-partner-1'$$,'55000',null,'aliases cannot be removed or reused');
set local role authenticated;
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000001',true);
insert into attribution_fixture values('slug_request',jsonb_build_object('partner_id','f8200000-0000-4000-8000-000000000001','slug','ozark-auto','expected_revision',1,'request_id','f8900000-0000-4000-8000-000000000001'));
insert into attribution_fixture select 'slug_response',public.referral_partner_operation('slug_update',(select value from attribution_fixture where key='slug_request'));
select is((select value->'partner'->>'url_slug' from attribution_fixture where key='slug_response'),'ozark-auto','manager changes current alias');
select is(public.referral_partner_operation('slug_update',(select value from attribution_fixture where key='slug_request')),(select value from attribution_fixture where key='slug_response'),'retry preserves exactly one update');
select throws_ok($$select public.referral_partner_operation('slug_update',(select value||'{"slug":"other-name","request_id":"f8900000-0000-4000-8000-000000000002"}'::jsonb from attribution_fixture where key='slug_request'))$$,'40001',null,'stale edits fail');
select throws_ok($$select public.referral_partner_operation('slug_update',(select value||'{"slug":"admin","request_id":"f8900000-0000-4000-8000-000000000002"}'::jsonb from attribution_fixture where key='slug_request'))$$,'22023',null,'reserved aliases fail');
select throws_ok($$select public.referral_partner_operation('slug_update',(select value||'{"partner_id":"f8200000-0000-4000-8000-000000000002","slug":"fixture-partner-1","request_id":"f8900000-0000-4000-8000-000000000002"}'::jsonb from attribution_fixture where key='slug_request'))$$,'23505',null,'retired alias remains reserved');
select is(public.referral_partner_operation('staff_resolve','{"slug":"fixture-partner-1"}')->'partner'->>'url_slug','ozark-auto','old admin alias resolves current record');
select is(public.referral_partner_operation('staff_referral_summary','{"partner_id":"f8200000-0000-4000-8000-000000000001"}')->'link'->>'slug','ozark-auto','share link uses the current readable alias');
select is(public.referral_partner_operation('staff_referral_summary','{"partner_id":"f8200000-0000-4000-8000-000000000001"}')->'link'->>'code',(select value->>'code' from attribution_fixture where key='link1'),'opaque code remains unchanged');
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000003',true);
select is(public.referral_partner_operation('partner_resolve','{"slug":"ozark-auto"}')->'partner'->>'id','f8200000-0000-4000-8000-000000000001','owner resolves readable private URL');
select throws_ok($$select public.referral_partner_operation('partner_resolve','{"slug":"fixture-partner-2"}')$$,'42501',null,'readable URLs do not expose another owner');
select throws_ok($$select public.referral_partner_operation('staff_resolve','{"slug":"ozark-auto"}')$$,'42501',null,'partners cannot resolve staff records');
select throws_ok($$select public.referral_partner_operation('slug_update',(select value from attribution_fixture where key='slug_request'))$$,'42501',null,'partners cannot edit aliases');
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000006',true);
select throws_ok($$select public.referral_partner_operation('partner_resolve','{"slug":"ozark-auto"}')$$,'42501',null,'unverified identities cannot resolve aliases');
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000005',true);
insert into attribution_fixture values('new_alias_case',to_jsonb(public.get_or_create_referred_total_loss_draft('ozark-auto')));
select is((public.get_or_create_referred_total_loss_draft('fixture-partner-2')).id,(select (value->>'id')::uuid from attribution_fixture where key='new_alias_case'),'a competing alias resumes without reattribution');
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000008',true);
insert into attribution_fixture values('old_alias_case',to_jsonb(public.get_or_create_referred_total_loss_draft('fixture-partner-1')));
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000007',true);
insert into attribution_fixture values('old_code_case',to_jsonb(public.get_or_create_referred_total_loss_draft((select value->>'code' from attribution_fixture where key='link1'))));
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000009',true);
insert into attribution_fixture values('ordinary_case',to_jsonb(public.get_or_create_referred_total_loss_draft('unknown-business')));
select is((public.get_or_create_referred_total_loss_draft('ozark-auto')).id,(select (value->>'id')::uuid from attribution_fixture where key='ordinary_case'),'existing ordinary draft is not replaced by a referral');
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000001',true);
select public.referral_partner_operation('link_state',jsonb_build_object('partner_id','f8200000-0000-4000-8000-000000000001','expected_revision',1,'enabled',false,'request_id','f8900000-0000-4000-8000-000000000003'));
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000010',true);
insert into attribution_fixture values('paused_case',to_jsonb(public.get_or_create_referred_total_loss_draft('fixture-partner-1')));
select set_config('request.jwt.claim.sub','f8100000-0000-4000-8000-000000000011',true);
insert into attribution_fixture values('inactive_case',to_jsonb(public.get_or_create_referred_total_loss_draft('fixture-partner-3')));
reset role;
select is((select count(*) from public.referral_case_attributions where partner_id='f8200000-0000-4000-8000-000000000001'),3::bigint,'new alias, retired alias, and old code all bind the same original link');
select is((select count(*) from public.referral_case_attributions where partner_id in ('f8200000-0000-4000-8000-000000000002','f8200000-0000-4000-8000-000000000003')),0::bigint,'no competing attribution');
select is((select count(*) from public.referral_case_attributions where case_id in (select (value->>'id')::uuid from attribution_fixture where key in ('ordinary_case','paused_case','inactive_case'))),0::bigint,'unknown, paused and inactive aliases do not attribute; existing drafts are not retrofitted');
select is((select count(*) from public.referral_partner_events where partner_id='f8200000-0000-4000-8000-000000000001' and event_type='partner.link_updated'),1::bigint,'one retained alias-change event');
set constraints all immediate;
select * from finish();
rollback;
